insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mt2_v1'
from (values
('117.320.c.1.A',2,'A second-year musical theatre student plans a pre-rehearsal routine. Which plan covers voice, body and dance together?','["Stretching, breathing exercises, humming and a light dance sequence", "Sitting still for ten minutes", "Loud shouting to start", "Reading the program notes"]'::jsonb,0,'Warm-ups should prepare voice and body.','original'),
('117.320.c.1.A',2,'Why does a performer warm up the voice before belting a high song at rehearsal?','["To avoid learning lyrics", "To reduce strain and prepare the vocal folds", "To make the song shorter", "To get louder than the band"]'::jsonb,1,'Warm-ups protect the voice.','original'),
('117.320.c.1.B',2,'A dancer practices a time step and shuffle-ball-change for a show number. Which genre is she working in?','["Mime only", "Folk waltz", "Tap", "Ballet adagio"]'::jsonb,2,'Time steps and shuffles belong to tap.','original'),
('117.320.c.1.B',2,'A character tells a story with gesture and facial expression and no words. This skill is called ___.','["Overture", "Reprise", "Libretto", "Pantomime"]'::jsonb,3,'Pantomime uses silent movement.','original'),
('117.320.c.1.C',3,'An actor plays a heartbreak scene, then sings the next song while keeping the same emotional truth. Which skill is she using?','["Carrying a character''s intention from speech into song", "Selling tickets", "Memorizing the pit score", "Building the set"]'::jsonb,0,'Acting must continue through song and dance.','original'),
('117.320.c.1.C',3,'What is a good way to keep a dance number in character?','["Ignore the story", "Let the character''s feelings drive each movement", "Look only at your feet", "Count out loud to the audience"]'::jsonb,1,'Dance should stay motivated by character.','original'),
('117.320.c.1.D',3,'A student prepares a 16-bar cut, a short monologue and a dance combination for a callback. She is practicing what?','["Program printing", "Stagehand duties", "Professional audition techniques", "Lighting design"]'::jsonb,2,'Auditions combine song, acting and movement.','original'),
('117.320.c.1.D',3,'Which choice best shows professionalism in an audition room?','["Argue about the casting", "Skip the introduction", "Arrive after the panel leaves", "Introduce yourself clearly, give the pianist the tempo, and thank the panel"]'::jsonb,3,'Preparedness and courtesy matter.','original'),
('117.320.c.1.E',3,'In many musicals, the first-act finale raises the conflict to a peak before intermission. This is part of the show''s ___.','["Dramatic structure", "Parking plan", "Costume budget", "Ticket policy"]'::jsonb,0,'Acts follow a dramatic arc.','original'),
('117.320.c.1.E',3,'Where in a musical does an ''I want'' song usually appear?','["Never in a musical", "Early, to show what the lead character wants", "After the curtain call", "Only in the finale"]'::jsonb,1,'The ''I want'' song sets up the goal.','original'),
('117.320.c.1.F',2,'Which term is a musical theatre word for the written text of the spoken scenes and lyrics?','["Pit and trap", "Fly and rail", "Book and lyrics", "Wing and drop"]'::jsonb,2,'The book is the spoken script.','original'),
('117.320.c.1.F',2,'The orchestra of a musical usually plays in the ___.','["Lobby", "Green room", "Scene shop", "Pit"]'::jsonb,3,'The pit holds the musicians.','original'),
('117.320.c.1.G',3,'A student reads the libretto to describe a character''s age, goals, feelings and background. This is a ___.','["Character analysis", "Set sketch", "Poster layout", "Costume repair"]'::jsonb,0,'Analysis covers physical, intellectual, emotional and social traits.','original'),
('117.320.c.1.G',3,'Which libretto clue best reveals a character''s social background?','["The cover color", "Word choice, dialect and how others address the character", "The font in the script", "The page count"]'::jsonb,1,'Language reveals social status.','original'),
('117.320.c.1.H',3,'The composer, lyricist, director and choreographer meet to agree on a song''s tempo and staging. This is ___.','["Auditioning", "Advertising", "Collaboration among artistic partners", "Competition"]'::jsonb,2,'Partners must align their ideas.','original'),
('117.320.c.1.H',3,'When a composer revises a key change, who should be told right away?','["Only the audience", "Nobody", "The ticket office only", "The musical director, performers and orchestra"]'::jsonb,3,'Changes affect everyone''s work.','original'),
('117.320.c.2.A',2,'A student feels vocal fatigue and a scratchy throat during tech week. What should she do?','["Rest, hydrate and tell the vocal coach", "Ignore it", "Sing louder", "Whisper-shout all night"]'::jsonb,0,'Rest and care prevent damage.','original'),
('117.320.c.2.A',2,'Which safety habit helps in a high-energy dance number?','["Hold your breath", "Clear the floor and wear secure, supportive shoes", "Skip the warm-up", "Dance in socks on wet floors"]'::jsonb,1,'Safe movement prevents injury.','original'),
('117.320.c.2.B',2,'An ensemble member invents a small comic bit that fits the scene. She is exploring ___.','["Silence", "Copying a film", "Creativity within an ensemble", "Rule breaking"]'::jsonb,2,'Ensembles can build creative choices together.','original'),
('117.320.c.2.B',2,'What helps an ensemble stay creative while sharing ideas?','["Skipping notes", "Blocking every idea", "Talking over others", "Listening and building on one another''s choices"]'::jsonb,3,'Yes-and builds ensemble creativity.','original'),
('117.320.c.2.C',3,'A comic revue and a dark psychological musical call for different acting choices. This is a difference in ___.','["Style and characterization", "Theatre size only", "Program font", "Ticket price"]'::jsonb,0,'Styles shape how characters are played.','original'),
('117.320.c.2.C',3,'How should a performer adjust her acting for a stylized fantasy musical compared with a realistic drama?','["Stand motionless", "Use bolder gestures and heightened expression", "Use no movement", "Whisper every line"]'::jsonb,1,'Stylized work is often heightened.','original'),
('117.320.c.2.D',3,'A singer drops her jaw, lifts her soft palate and supports with the abdominal muscles. She is using good ___.','["Prop handling", "Rigging", "Vocal technique", "Stage lighting"]'::jsonb,2,'Technique shapes tone.','original'),
('117.320.c.2.D',3,'Which habit helps clear diction in a fast patter song?','["Tight jaw clenching", "Singing in a whisper", "Mumbling the vowels", "Crisp consonants and relaxed articulators"]'::jsonb,3,'Articulation clarifies words.','original'),
('117.320.c.2.E',3,'Reading a song''s lyrics for repeated words and changes in mood helps an actor decide how to ___.','["Shape the character''s emotions and movement", "Hang lights", "Order flowers", "Print the tickets"]'::jsonb,0,'Lyrics guide choices.','original'),
('117.320.c.2.E',3,'A lyric changes from soft images to harsh ones in the bridge. How might the dancer respond?','["Repeat the same step unchanged", "Shift from flowing to sharp movement", "Face upstage the whole time", "Stop moving"]'::jsonb,1,'Movement mirrors lyric shifts.','original'),
('117.320.c.2.F',3,'An actor keeps a villain''s posture, voice and walk steady through a full number. She is ___ the character.','["Cutting", "Erasing", "Sustaining", "Printing"]'::jsonb,2,'Believable characters stay consistent.','original'),
('117.320.c.2.F',3,'Which trio of tools builds a believable character in a musical?','["Fonts, colors and logos", "Lights, curtains and tickets", "Paint, glue and nails", "Voice, body and dance movement"]'::jsonb,3,'Characterization uses voice, body and dance.','original'),
('117.320.c.2.G',3,'A student writes a new verse and a short dance phrase for a class showcase. She is ___ material.','["Composing", "Auditing", "Reviewing only", "Erasing"]'::jsonb,0,'Creating new work is composing.','original'),
('117.320.c.2.G',3,'Which piece could a student compose for a musical theatre class project?','["A grocery list", "Original lyrics for a scene", "A bus schedule", "A tax form"]'::jsonb,1,'Lyrics are original material.','original'),
('117.320.c.3.A',2,'Before using a wireless microphone pack, the performer should ___.','["Hide it in a prop bin", "Drop it to test", "Have it fitted and checked by the sound crew", "Hang it on a light"]'::jsonb,2,'Technical elements need safe handling.','original'),
('117.320.c.3.A',2,'Why are quick-change rules posted backstage in a musical?','["To shorten songs", "To slow the show", "To decorate the wall", "To keep dressers and actors safe in the dark"]'::jsonb,3,'Safety rules prevent accidents.','original'),
('117.320.c.3.B',3,'Who guides actors on character and staging, while another leader teaches the vocal parts?','["Director and musical director", "Cashier and clerk", "Usher and box office", "Janitor and driver"]'::jsonb,0,'Each leader has a role.','original'),
('117.320.c.3.B',3,'Which person is mainly responsible for the dance staging in a musical?','["Prop master", "Choreographer", "House manager", "Playwright only"]'::jsonb,1,'The choreographer designs movement.','original'),
('117.320.c.3.C',3,'A production plan lists research, a rehearsal schedule, blocking notes and technical cues. Its purpose is to ___.','["Replace actors", "Delay the opening", "Organize the show''s development", "Avoid planning"]'::jsonb,2,'Plans keep a production on track.','original'),
('117.320.c.3.C',3,'A rehearsal schedule works best when it ___.','["Skips the dance calls", "Has no end time", "Calls everyone all the time", "Matches each scene to the people needed"]'::jsonb,3,'Efficient schedules respect time.','original'),
('117.320.c.3.D',3,'The lights fail during a song at rehearsal and the actors stay calm and keep going safely. This shows ___.','["Responsibility and creative problem solving", "Quitting", "Blaming", "Panic"]'::jsonb,0,'Good teams adapt.','original'),
('117.320.c.3.D',3,'A prop is missing before a scene. A crew member finds a safe substitute. She is ___.','["Deleting", "Problem solving", "Dodging", "Delaying"]'::jsonb,1,'Solutions keep the show moving.','original'),
('117.320.c.3.E',3,'A student takes a technician role one week and a role as actor the next. This helps her ___.','["Work only alone", "Skip safety", "Understand the show from several jobs", "Avoid rehearsal"]'::jsonb,2,'Varied roles build understanding.','original'),
('117.320.c.3.E',3,'A good ensemble partner in a production does what?','["Ignores cues", "Cancels last minute", "Works against the director", "Does the job reliably and supports the team"]'::jsonb,3,'Reliability helps collaboration.','original'),
('117.320.c.4.A',3,'Operetta, minstrel shows and vaudeville each shaped early American stage entertainment. This is a ___.','["Historical influence", "Ticket trend", "Costume fabric", "Lighting cue"]'::jsonb,0,'Earlier forms shaped musicals.','original'),
('117.320.c.4.A',3,'Immigrant communities in New York brought songs and humor to early theatre. This shows a ___ influence.','["Mechanical", "Cultural", "Weather", "Chemical"]'::jsonb,1,'Cultures contribute to theatre.','original'),
('117.320.c.4.B',3,'Why is the musical sometimes called a uniquely American art form?','["It uses no music", "It has no stories", "It blended many American styles of music, dance and storytelling", "It came from one country in Asia"]'::jsonb,2,'American styles blended into musicals.','original'),
('117.320.c.4.B',3,'Which landmark 1943 show merged story, song and dance in a new way?','["Hamilton", "Rent", "Wicked", "Oklahoma!"]'::jsonb,3,'Oklahoma! integrated song and dance into plot.','original'),
('117.320.c.4.C',3,'The jukebox musical builds a story around a catalog of existing popular songs. This is a ___ in musical theatre.','["Development", "Prop", "Lighting rig", "Mistake"]'::jsonb,0,'New forms keep emerging.','original'),
('117.320.c.4.C',3,'Concept musicals of the 1970s focused on a theme rather than a simple plot. This changed ___.','["The color of the curtain", "How shows were structured", "Only the ticket price", "The size of seats"]'::jsonb,1,'Structure evolved.','original'),
('117.320.c.4.D',3,'A new composer writes a musical that mixes hip-hop with traditional Broadway style. This illustrates ___.','["A radio drama", "Ancient Greek drama", "Contemporary development of musical theatre", "A silent film"]'::jsonb,2,'Contemporary writers blend styles.','original'),
('117.320.c.4.D',3,'Modern composers often add which element to widen the range of musical theatre voices?','["No music", "No dancing", "Only one genre", "Diverse cultures and genres"]'::jsonb,3,'Diversity broadens the form.','original'),
('117.320.c.4.E',3,'A musical set during a war reflects the ___ of its time and place.','["Concerns and culture", "Parking rules", "Ticket prices only", "Seat colors"]'::jsonb,0,'Musicals mirror their settings.','original'),
('117.320.c.4.E',3,'How might a musical show life in a particular culture?','["By using no setting", "Through its music, dance, dress and stories", "By removing all characters", "By hiding the story"]'::jsonb,1,'Details express culture.','original'),
('117.320.c.4.F',3,'A movie musical hits theaters, then a stage version is mounted from it. This shows how forms ___.','["Never touch", "Ignore the audience", "Influence one another", "Replace all theatre"]'::jsonb,2,'Media cross over.','original'),
('117.320.c.4.F',3,'Which pairing shows television influencing musical theatre?','["A building plan", "A poster of a painting", "A sculpture", "A live televised broadcast of a stage musical"]'::jsonb,3,'Television presents musicals live.','original'),
('117.320.c.5.A',2,'At a recital with a large audience, which behavior is appropriate?','["Quiet attention and applause at the end of pieces", "Walking across the aisle during songs", "Texting loudly", "Calling out to friends"]'::jsonb,0,'Respect performers and audience.','original'),
('117.320.c.5.A',2,'Different performances ask for different audience behavior. At a rock-style musical, which is often acceptable?','["Throwing food", "Cheering at moments the cast invites it", "Taking the stage", "Yelling insults"]'::jsonb,1,'Etiquette adapts to the show.','original'),
('117.320.c.5.B',3,'A student describes how musical theatre mixes music, drama and dance to move an audience. She is describing it as ___.','["A diet", "A trade", "An art form", "A sport"]'::jsonb,2,'Musical theatre is an art form.','original'),
('117.320.c.5.B',3,'Self-evaluation of your creativity after a performance helps you ___.','["Skip practice", "Blame others", "Avoid feedback", "Set goals for growth"]'::jsonb,3,'Reflection guides improvement.','original'),
('117.320.c.5.C',3,'Which peer comment is constructive?','["Your diction was clear, and the second verse could use more breath support", "You should quit", "That was dumb", "Nobody cared"]'::jsonb,0,'Specific, kind and useful.','original'),
('117.320.c.5.C',3,'Why give feedback that is specific?','["It waits for opening night", "It shows exactly what to keep or change", "It ends the show", "It hides the problem"]'::jsonb,1,'Specific feedback can be used.','original'),
('117.320.c.5.D',3,'A review mentions the harmony in the quartet, the quality of the sets and the pacing of act two. It is ___.','["Vague", "Off topic", "Specific and detailed", "Unreadable"]'::jsonb,2,'Details support an evaluation.','original'),
('117.320.c.5.D',3,'Which sentence is the most precise observation?','["Good vibes", "It was fine", "It was nice", "The lead''s vibrato relaxed in the final chorus and the tempo drove the scene"]'::jsonb,3,'Precision describes what happened.','original'),
('117.320.c.5.E',3,'A musical''s story, songs, dance, design and orchestra all rely on one another. This is called ___.','["Interdependence", "Randomness", "Isolation", "Competition"]'::jsonb,0,'Elements depend on each other.','original'),
('117.320.c.5.E',3,'If a scene change takes too long, what element of the show is weakened?','["The weather", "Pacing", "The ticket color", "The program"]'::jsonb,1,'Elements affect pacing.','original'),
('117.320.c.5.F',3,'Which is an avocational opportunity in musical theatre?','["Selling cars", "Repairing roads", "Performing in a community theatre production", "Driving a bus"]'::jsonb,2,'Avocational means pursued for love of it.','original'),
('117.320.c.5.F',3,'Which career is found in musical film?','["Pilot", "Tax auditor", "Plumber", "Film choreographer"]'::jsonb,3,'Choreographers work in film musicals.','original'),
('117.320.c.5.G',3,'Confidence from performing helps a student in a job interview. This links musical theatre to ___.','["Careers outside of theatre", "Nothing", "Only dance classes", "Only a talent show"]'::jsonb,0,'Skills transfer.','original'),
('117.320.c.5.G',3,'Which skill from rehearsal also helps in a college group project?','["Skipping class", "Meeting deadlines and cooperating", "Cutting corners", "Ignoring teammates"]'::jsonb,1,'Teamwork transfers.','original'),
('117.320.c.5.H',3,'A student records a performance and builds an annotated video portfolio. She is ___.','["Skipping reflection", "Deleting evidence", "Documenting and presenting information with technology", "Hiding her work"]'::jsonb,2,'Portfolios use technology.','original'),
('117.320.c.5.H',3,'A good digital portfolio of musical theatre work includes ___.','["Random folders", "No content", "Blurry unlabeled files", "Clear titles, dates and notes on each piece"]'::jsonb,3,'Clear organization helps viewers.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
